    var REF = { closeX: 1591, closeY: 54, closeHelpDx: 129, x: 1055, y: 934, legendX: 412, w: 200, h: 44 };
    var SLOTS = 15, COLS = 5, ROWS = 3, BATTLE_FROM = 6, BATTLE_TO = 9, DEFAULT_W = [10, 10, 50, 10];

    function toast(t) { try { PromptBox.getInstance().updataTxt(t); } catch (e) { } }
    function edge(v) { v = Number(v); return v >= 1 && v <= 4 ? v : 0; }
    function colorsOf(box) { return box ? [edge(box.top), edge(box.right), edge(box.bottom), edge(box.left)] : null; }
