        var before = evaluate(base, W), seed = 7;
        for (i = 0; i < free.length; i++) seed = (seed * 31 + Number(String(ids[i]).replace(/\D/g, '').slice(-6) || 0)) >>> 0;
        var order = optimize(base, free, W, seed), next = base.slice(0), assign = [];
