        var unit = Math.abs(wc.x - wh.x) / REF.closeHelpDx;
        if (!(unit > 0) || !isFinite(unit))
            return;
        var world = cc.p(wc.x + (REF.x - REF.closeX) * unit, wc.y - (REF.y - REF.closeY) * unit);
        var p0 = scene.convertToNodeSpace(world), p1 = scene.convertToNodeSpace(cc.p(world.x + unit, world.y));
