var __NH_LANG_API = null;
function __NH_INSTALL_LANGUAGE() {
    if (__NH_LANG_API) return;
    var KEY = 'nh_lang_v1', LANGS = ['en', 'id', 'ja'], base = {}, cur = 'en';
    try { var saved = sys.localStorage.getItem(KEY); if (LANGS.indexOf(saved) >= 0) cur = saved; } catch (e) { }
    function textFor(lang, id) {
        var b = base[id], m = lang === 'en' ? null : __NH_LANG_DATA[lang];
        return (m && m[id] !== undefined) ? m[id] : b;
    }
    // dipanggil oleh loader tabel Text saat mengisi Config.textObject (lihat __nhLangText di recovered-runtime.js)
    function hook(id, t) {
        if (typeof t !== 'string') return t;
        base[id] = t;
        return cur === 'en' ? t : textFor(cur, id);
    }
    function adopt() {            // teks yang sudah terisi sebelum hook terpasang dianggap English asli
        try {
            var to = Config.getInstance().textObject, id;
            for (id in __NH_LANG_DATA.id) if (base[id] === undefined && typeof to[id] === 'string') base[id] = to[id];
            return to;
        } catch (e) { return null; }
    }
    function apply(prev, next) {
        var to = adopt(), id;
        if (!to) return;
        for (id in base) {
            if (__NH_LANG_DATA.id[id] === undefined) continue;
            if (to[id] === textFor(prev, id)) to[id] = textFor(next, id);   // teks yang ditimpa adapter (custom) dibiarkan
        }
    }
    function setLang(l) {
        if (LANGS.indexOf(l) < 0 || l === cur) return;
        var prev = cur;
        cur = l;
        try { sys.localStorage.setItem(KEY, l); } catch (e) { }
        apply(prev, l);
    }
    function ui(s) {              // label baris Settings
        var m = { id: { 'Voice': 'Suara', 'Night Mode': 'Mode Malam', 'Change Account': 'Ganti Akun', 'Redeem Code': 'Kode Tukar', 'Language': 'Bahasa', 'Background': 'Latar', 'Switch': 'Ganti', 'Open': 'Buka' },
                  ja: { 'Voice': '音声', 'Night Mode': 'ナイトモード', 'Change Account': 'アカウント切替', 'Redeem Code': '引換コード', 'Language': '言語', 'Background': '背景', 'Switch': '切替', 'Open': '開く' } }[cur];
        return (m && m[s]) || s;
    }
    __NH_LANG_API = {
        get: function () { return cur; },
        label: function () { return { en: 'English', id: 'Indonesia', ja: 'Japanese' }[cur]; },
        cycle: function () { setLang(LANGS[(LANGS.indexOf(cur) + 1) % LANGS.length]); },
        ui: ui
    };
    var hookTries = 0;
    (function bind() {
        try { __nhLangSet(hook); } catch (e) { if (++hookTries < 40) setTimeout(bind, 250); }
    })();
    // teks mungkin sudah dimuat sebelum adapter ini jalan; coba beberapa kali sampai Config siap
    if (cur !== 'en') {
        var tries = 0, timer = function () {
            var to = adopt();
            if (to && Object.keys(to).length) { apply('en', cur); return; }
            if (++tries < 40) setTimeout(timer, 500);
        };
        timer();
    }
    try { GameConnection.__nhLang = __NH_LANG_API; } catch (e) { }
}

