    var BUSY_TEXT = { fightOpen: 'Loading', fightChallenge: 'Sending challenge', fightClaim: 'Claiming reward', fightAccept: 'Joining fight', fightLeave: 'Leaving fight' };
    var BUSY_END = { fightLobby: 1, fightMsg: 1, fightStart: 1, fightEnd: 1, fightClaimResult: 1 };
    var BUSY = { L: null, tm: null, base: '', n: 0 }, WAIT = { L: null, end: 0 };
