        var pw = Math.min(W - 40, 520), ph = 280;
        L.addChild(box(30, 18, 26, 245, pw, ph, cx - pw / 2, cy - ph / 2), 1);
        L.addChild(box(250, 200, 80, 255, pw, 4, cx - pw / 2, cy + ph / 2 - 4), 2);
