        var s = String(name || '?'), hsh = 0, i; for (i = 0; i < s.length; i++) hsh = (hsh * 31 + s.charCodeAt(i)) % 997;
        var ac = AV_COLORS[hsh % AV_COLORS.length], disc = spr(IMG + 'nh_fight_avatar.png');
