        var H = GameTools.getInstance().sceneSize.height;
        function T(fromRight, yTop) { return cc.p(-fromRight * K, H - yTop * K); }   // koordinat HomeMenu (x=0 di tepi kanan layar)
        var R = cc.Layer.create(); hm.addChild(R, 10);

        var leave = spr(mode === 'map' ? 'map_leave.png' : 'hl_leave.png'); var LX = (mode === 'map') ? 84 : 136.5; leave.setPosition(T(LX, 32)); R.addChild(leave);
        var leaveTF = lbl(mode === 'map' ? 'Enter Village' : 'Leave Village', 13, cc.c3b(70, 40, 10)); leaveTF.setPosition(T(LX, 32)); R.addChild(leaveTF, 1); if (mode === 'map') leaveTF.setVisible(false);   // di peta teks sudah ada di gambar tombol
        var leaveDot = spr('hl_dot.png'); leaveDot.setPosition(T(LX - 56.5, 18)); R.addChild(leaveDot, 2); leaveDot.setVisible(false);

        var burger = spr(mode === 'map' ? 'map_burger.png' : 'hl_burger.png'); burger.setPosition(T(42, 32)); R.addChild(burger, 2);
        burger._ty = 'nhBurger';
        var dot = spr('hl_dot.png'); dot.setPosition(T(26, 16)); R.addChild(dot, 3); dot.setVisible(false);

        var panel = cc.Node.create(); panel.setVisible(false); R.addChild(panel, 1);
        var bg2 = spr('hl_panel.png'), bg3 = spr('hl_panel3.png'), bg2w = spr('hl_panel2w.png'), bg3w = spr('hl_panel3w.png');
        var bgs = [bg2, bg3, bg2w, bg3w], bi;
        for (bi = 0; bi < bgs.length; bi++) { bgs[bi].setAnchorPoint(cc.p(1, 1)); bgs[bi].setPosition(T(20, 64)); bgs[bi].setScale(bgs[bi].getScale() * MF); panel.addChild(bgs[bi]); }
        var title = lbl('Menu', 14, cc.c3b(255, 200, 70), 0, 0.5); title.setPosition(T(mx(326), my(85))); title.setScale(MF); panel.addChild(title, 2);

        if (mode === 'map') { burger.setVisible(false); dot.setVisible = function () { }; }   // di peta tidak ada tombol hamburger
