            var icn = spr(it.ic); icn.setScale(icn.getScale() * MF); panel.addChild(icn, 2);
            var tf = lbl(it.lab, 12, cc.c3b(255, 255, 255)); tf.setScale(MF); panel.addChild(tf, 2);
            var td = spr('hl_dot.png'); td.setScale(td.getScale() * MF); panel.addChild(td, 3); td.setVisible(false);
