        for (i = 0; i < cf.bolt.length; i++) { s0 = img('bolt' + cf.bolt[i][0] + '.png', cf.bolt[i][1], cf.bolt[i][2], 4, true); if (s0) { s0.setOpacity(0); bolts.push(s0); } }
