            var sz = rnd(2, 4), em = cc.LayerColor.create(cc.c4b(255, rnd(120, 180), 50, 255), sz, sz);
            em.setOpacity(rnd(110, 230)); fx.addChild(em, 5);
            embers.push({ n: em, x: rnd(0, cs.width), y: rnd(e0, e1), vy: rnd(10, 26) * BG_EMBER * 2, ph: rnd(0, 6.28), sw: rnd(8, 24) });
