    function toast(root, text) {
        say(text);
        if (!NH_LAVA_TOAST || !root) return null;
        try {
            var l = cc.LabelTTF.create(text, 'Helvetica', 20);
            var ws = cc.director.getWinSize();
            l.setPosition(cc.p(ws.width / 2, ws.height - 150));
            try { l.setColor(cc.c3b(255, 220, 80)); } catch (e0) { }
            root.addChild(l, 99999);
            return l;
        } catch (e) { return null; }
    }

