        var aw = bb.width > 10 ? bb.width : (cs.width > 10 ? cs.width : 120), ah = bb.height > 10 ? bb.height : (cs.height > 10 ? cs.height : 36);
        var cx = bb.width > 10 ? bb.x + bb.width / 2 : anchor.getPosition().x, top = bb.height > 10 ? bb.y : anchor.getPosition().y - ah / 2;
        var bh = Math.max(20, Math.round(ah * 0.62)), aWd = bh, rWd = Math.round(bh * 1.8), gap = Math.max(3, Math.round(aw * 0.03));
        var total = aWd * 2 + rWd + gap * 2, x0 = Math.round(cx - total / 2), y0 = Math.round(top - ah * 0.2 - bh), i;

