        c.buildUI();
        try { c.target = vl.target; } catch (e) { }
        c.updata(row, rankIdx);
        card.addChild(c, 5);
        try { (vl.__nhCards = vl.__nhCards || []).push({ c: c, card: card, w: cw, h: h }); } catch (e) { }
