            tl.setAnchorPoint(cc.p(0.5, 0.5));
            tl.setScale(0.82);
            var tw = tl.getContentSize().width * 0.82, lw = c.logoImage ? 29 : 0, gp = 6;
            if (tw + lw + gp > cw - 14) tl.setScale(0.82 * (cw - 14 - lw - gp) / tw);
