// ===== NH: tabel level gedung (Summon/Ninja School) diperluas sampai Lv 20 =====
// build_skill (kualitas skill per level gedung) hanya punya 10 isi dan build_skill_level 11 isi. Gedung kini bisa naik >10,
// sehingga build_skill[lv-1] = undefined -> setColor(undefined) = "Error processing arguments" -> layar Summon School gagal dibuka.
(function installSchoolLevelTables() {
    'use strict';
    function grow(arr, len) {
        if (!arr || typeof arr.length !== 'number' || arr.length < 1) return;
        var last = arr[arr.length - 1];
        while (arr.length < len) arr.push(last);
    }
    try { if (typeof build_skill !== 'undefined') grow(build_skill, 20); } catch (e) { }
    try { if (typeof build_skill_level !== 'undefined') grow(build_skill_level, 21); } catch (e) { }
    try { log('NH_SCHOOLTBL siap'); } catch (e) { }
}());

// ===== Rapikan notifikasi: bubble ninja, pesan "penuh" ganda, toast berulang =====
(function () {
    // 2) Toast: pesan yang sama tidak diulang < 2 detik (tap berulang / loop klaim), dan semua pesan "penuh" yang
    //    teksnya identik (id 100-104) dipetakan ke satu id supaya tidak muncul bertumpuk.
    if (typeof PromptBox !== 'undefined' && PromptBox.prototype && !PromptBox.prototype.__nhToastDedupe) {
        var lastKey = '', lastAt = 0, now = function () { return new Date().getTime(); };
        var allow = function (key) {
            var t = now();
            if (key === lastKey && t - lastAt < 2000) return false;
            lastKey = key; lastAt = t;
            return true;
        };
        var origTxt = PromptBox.prototype.updataTxt, origTid = PromptBox.prototype.updataTid;
        if (typeof origTxt === 'function')
            PromptBox.prototype.updataTxt = function (text) {
                if (!allow('t:' + String(text))) return;
                return origTxt.apply(this, arguments);
            };
        if (typeof origTid === 'function')
            PromptBox.prototype.updataTid = function (id, args) {
                var n = Number(id);
                if (n >= 100 && n <= 104) { n = 100; arguments[0] = 100; }
                if (!allow('i:' + n + ':' + (args ? args.join('|') : ''))) return;
                return origTid.apply(this, arguments);
            };
        PromptBox.prototype.__nhToastDedupe = true;
    }
}());







