// ── Summon School slot machine: skill SSS (quality 7) / UR (quality 8) ─────────────────────────────
// Klien memilih pola reel dengan BanditData[6 - quality] (SS = 0 ... D = 5). Quality 7/8 -> indeks -1/-2 = undefined,
// reel tidak pernah berhenti ("muter terus"). Pola SSS/UR dibuat sama dengan SS: ketiga reel menunjukkan simbol yang sama.
(function NH_BANDIT_SSS() {
    function fix() {
        try {
            if (typeof BanditData === 'undefined' || !BanditData || !BanditData[0]) return false;
            if (!BanditData[-1]) BanditData[-1] = BanditData[0].slice();   // quality 7 (SSS)
            if (!BanditData[-2]) BanditData[-2] = BanditData[0].slice();   // quality 8 (UR / SR)
            return true;
        } catch (e) { return false; }
    }
    if (fix()) return;
    var tries = 0;
    (function again() { if (fix() || ++tries > 40) return; setTimeout(again, 500); }());
}());

