        var all = (Config.getInstance().adventureObject || {})[type] || {}, rows = [], list = all[ch] || [], i, r;
        for (i = 0; i < list.length; i++) if (list[i]) rows.push(list[i]);
        rows.sort(function (a, b) { return parseInt(a.stage, 10) - parseInt(b.stage, 10); });
        var doneArr = ((type === 1 ? ad.adv : ad.eadv) || [])[ch - 1] || [], doneMap = {};
        for (i = 0; i < doneArr.length; i++) doneMap[parseInt(doneArr[i], 10)] = 1;
        var maxMain = 0;
        for (i = 0; i < rows.length; i++) if (parseInt(rows[i].mainThread, 10) === 1) maxMain = Math.max(maxMain, parseInt(rows[i].stage, 10));
        var mainDone = true;
