        page.addChild(st.root, 999); page.__nhSM = st; NH_STAGE_PAGE = page;
        try { var sc0 = NH_CS_SCENE; if (sc0) { st.hid = []; [sc0.homeMenu].forEach(function (nd) { if (nd && nd.isVisible && nd.isVisible()) { nd.setVisible(false); st.hid.push(nd); } }); } } catch (e) { }
        st.root.addChild(cc.LayerColor.create(cc.c4b(8, 7, 26, 40), W, H), 0);
