            var ttl = lab(NH_CH_TITLE(G.ch), cx, H / 2 + 320 - 38, 34, [255, 178, 74]); try { var tw = ttl.getContentSize().width; if (tw > 520) ttl.setScale(520 / tw); } catch (eT) { } box.addChild(ttl, 3);
            var by = H / 2 + 320 - 44, back = spr('nh_cs_back.png', cx - 568 + 28 + 78, by); if (back) box.addChild(back, 3);
            st.hits.push({ x: cx - 568 + 28, y: by - 24, w: 156, h: 48, fn: function () { st.back(); } });
            var start = st.page * PER_PAGE, slice = G.nodes.slice(start, start + PER_PAGE), pts = [], n;
